INSERT INTO regulatory_sources (id, title, authority, jurisdiction_id, url, document_type, effective_date, last_verified_at, verified_by, status, supersedes_id, s3_key, fictional) VALUES ('src-hc-food-2025', 'Food Service Establishment Plan Review Guide', 'Harrow County Environmental Health Division', 'j-harrow', 'https://health.harrow-county.example/food/plan-review-guide-2025.pdf', 'guidance', '2025-03-01', '2026-09-22', 'u-rosa', 'approved', NULL, 'sources/j-harrow/src-hc-food-2025.pdf', true);
INSERT INTO source_sections (source_id, id, ordinal, heading, body) VALUES ('src-hc-food-2025', 's1', 0, '1. Purpose', 'This guide describes the materials an applicant must submit for plan review of a new or remodeled food service establishment in Harrow County. Applicants should contact the Division to confirm current requirements before submitting.');
INSERT INTO source_sections (source_id, id, ordinal, heading, body) VALUES ('src-hc-food-2025', 's2', 1, '2. Required submittal documents', 'The applicant must submit the following with the plan review application: (a) a completed Plan Review Application form signed by the owner or authorized agent; (b) a scaled floor plan showing the location of all food preparation, storage, warewashing and restroom areas; (c) an equipment schedule listing the make and model of each piece of food equipment; (d) a proposed menu, including any items served raw or undercooked; (e) a copy of a current food protection manager certificate for at least one person in charge.');
INSERT INTO source_sections (source_id, id, ordinal, heading, body) VALUES ('src-hc-food-2025', 's3', 2, '3. Conditional documents', 'If food will be prepared at another location, the applicant must submit a signed commissary agreement. If the establishment is served by a private water supply, the applicant must submit a water test report from an accredited laboratory.');
INSERT INTO source_sections (source_id, id, ordinal, heading, body) VALUES ('src-hc-food-2025', 's4', 3, '4. Pre-opening inspection', 'A pre-opening inspection must be completed and approved by the Division before the establishment operates. The applicant is responsible for scheduling the inspection after construction is complete.');
INSERT INTO regulatory_sources (id, title, authority, jurisdiction_id, url, document_type, effective_date, last_verified_at, verified_by, status, supersedes_id, s3_key, fictional) VALUES ('src-hc-food-2026', 'Food Service Establishment Plan Review Guide (Revised)', 'Harrow County Environmental Health Division', 'j-harrow', 'https://health.harrow-county.example/food/plan-review-guide-2026.pdf', 'guidance', '2026-12-01', '2026-10-15', 'u-rosa', 'pending_review', 'src-hc-food-2025', 'sources/j-harrow/src-hc-food-2026.pdf', true);
INSERT INTO source_sections (source_id, id, ordinal, heading, body) VALUES ('src-hc-food-2026', 's1', 0, '1. Purpose', 'This guide describes the materials an applicant must submit for plan review of a new or remodeled food service establishment in Harrow County. Applicants should contact the Division to confirm current requirements before submitting.');
INSERT INTO source_sections (source_id, id, ordinal, heading, body) VALUES ('src-hc-food-2026', 's2', 1, '2. Required submittal documents', 'The applicant must submit the following with the plan review application: (a) a completed Plan Review Application form signed by the owner or authorized agent; (b) a scaled floor plan showing the location of all food preparation, storage, warewashing and restroom areas; (c) an equipment schedule listing the make and model of each piece of food equipment; (d) a proposed menu, including any items served raw or undercooked; (e) a copy of a current food protection manager certificate for at least one person in charge; (f) a grease interceptor sizing worksheet, where the establishment discharges to the public sewer.');
INSERT INTO source_sections (source_id, id, ordinal, heading, body) VALUES ('src-hc-food-2026', 's3', 2, '3. Conditional documents', 'If food will be prepared at another location, the applicant must submit a signed commissary agreement. If the establishment is served by a private water supply, the applicant must submit a water test report from an accredited laboratory.');
INSERT INTO source_sections (source_id, id, ordinal, heading, body) VALUES ('src-hc-food-2026', 's4', 3, '4. Pre-opening inspection', 'A pre-opening inspection must be completed and approved by the Division before the establishment operates. The applicant is responsible for scheduling the inspection after construction is complete.');
INSERT INTO regulatory_sources (id, title, authority, jurisdiction_id, url, document_type, effective_date, last_verified_at, verified_by, status, supersedes_id, s3_key, fictional) VALUES ('src-ab-ti-2024', 'Commercial Tenant Improvement Submittal Checklist', 'City of Alderbrook Building Division', 'j-alderbrook', 'https://permits.alderbrook.example/building/ti-submittal-checklist.pdf', 'checklist', '2024-07-15', '2026-08-30', 'u-rosa', 'approved', NULL, 'sources/j-alderbrook/src-ab-ti-2024.pdf', true);
INSERT INTO source_sections (source_id, id, ordinal, heading, body) VALUES ('src-ab-ti-2024', 's1', 0, 'Applicability', 'This checklist applies to interior alterations of existing commercial spaces within the City of Alderbrook. It does not apply to new buildings or additions.');
INSERT INTO source_sections (source_id, id, ordinal, heading, body) VALUES ('src-ab-ti-2024', 's2', 1, 'Plans and drawings', 'Submit two sets of construction drawings prepared and signed by a design professional licensed in the State of Northmere. Drawings must include a site plan identifying the tenant space, a floor plan of existing and proposed conditions, and a code analysis sheet.');
INSERT INTO source_sections (source_id, id, ordinal, heading, body) VALUES ('src-ab-ti-2024', 's3', 2, 'Supporting documents', 'Each submittal must include a copy of the contractor''s current state license, a letter of authorization from the property owner if the applicant is not the owner, and completed energy compliance forms for any lighting or mechanical alterations.');
INSERT INTO source_sections (source_id, id, ordinal, heading, body) VALUES ('src-ab-ti-2024', 's4', 3, 'Structural work', 'Where the alteration affects structural elements, structural calculations stamped by a licensed engineer are required.');
INSERT INTO regulatory_sources (id, title, authority, jurisdiction_id, url, document_type, effective_date, last_verified_at, verified_by, status, supersedes_id, s3_key, fictional) VALUES ('src-ab-sign-2025', 'Permanent Sign Permit Application Requirements', 'City of Alderbrook Planning Department', 'j-alderbrook', 'https://permits.alderbrook.example/planning/sign-permit-requirements.pdf', 'application_form', '2025-01-06', '2026-07-11', 'u-rosa', 'approved', NULL, 'sources/j-alderbrook/src-ab-sign-2025.pdf', true);
INSERT INTO source_sections (source_id, id, ordinal, heading, body) VALUES ('src-ab-sign-2025', 's1', 0, 'Submittal requirements', 'A permanent sign permit application must include a scaled elevation drawing of each sign showing dimensions, materials and colors, and a site plan or building elevation showing the proposed sign location.');
INSERT INTO source_sections (source_id, id, ordinal, heading, body) VALUES ('src-ab-sign-2025', 's2', 1, 'Property owner consent', 'Written consent from the property owner is required for all signs on leased premises.');
INSERT INTO source_sections (source_id, id, ordinal, heading, body) VALUES ('src-ab-sign-2025', 's3', 2, 'Illuminated signs', 'Illuminated signs require proof that the sign is listed by a nationally recognized testing laboratory, and a separate electrical permit may be required. Applicants should confirm electrical permit requirements with the Building Division.');
INSERT INTO regulatory_sources (id, title, authority, jurisdiction_id, url, document_type, effective_date, last_verified_at, verified_by, status, supersedes_id, s3_key, fictional) VALUES ('src-nm-bev-2023', 'On-Premises Beverage License Application Instructions', 'Northmere Beverage Control Board', 'j-northmere', 'https://bcb.northmere.example/licensing/on-premises-instructions.pdf', 'guidance', '2023-11-01', '2026-09-05', 'u-rosa', 'approved', NULL, 'sources/j-northmere/src-nm-bev-2023.pdf', true);
INSERT INTO source_sections (source_id, id, ordinal, heading, body) VALUES ('src-nm-bev-2023', 's1', 0, 'Application materials', 'Applicants must provide a diagram of the licensed premises identifying all areas where beverages will be stored, served or consumed, and a copy of the executed lease or deed for the premises.');
INSERT INTO source_sections (source_id, id, ordinal, heading, body) VALUES ('src-nm-bev-2023', 's2', 1, 'Personal history disclosures', 'Each owner, officer and manager must complete a personal history disclosure form.');
INSERT INTO source_sections (source_id, id, ordinal, heading, body) VALUES ('src-nm-bev-2023', 's3', 2, 'Local zoning verification', 'The application must include a zoning verification letter issued by the local jurisdiction confirming that the proposed use is permitted at the premises.');
INSERT INTO source_sections (source_id, id, ordinal, heading, body) VALUES ('src-nm-bev-2023', 's4', 3, 'Public notice', 'The applicant must post the public notice provided by the Board at the premises in the manner described in the notice. Applicants should follow the posting instructions in the notice issued for their application.');
INSERT INTO regulatory_sources (id, title, authority, jurisdiction_id, url, document_type, effective_date, last_verified_at, verified_by, status, supersedes_id, s3_key, fictional) VALUES ('src-pl-bizlic-2025', 'Business Operating License — Application and Renewal', 'City of Port Linden Revenue Office', 'j-portlinden', 'https://revenue.portlinden.example/business-license/overview.html', 'guidance', '2025-06-01', '2026-10-02', 'u-rosa', 'approved', NULL, NULL, true);
INSERT INTO source_sections (source_id, id, ordinal, heading, body) VALUES ('src-pl-bizlic-2025', 's1', 0, 'New applications', 'A new business operating license application must include the business''s state registration number, a description of business activities, and proof of the right to occupy the business location.');
INSERT INTO source_sections (source_id, id, ordinal, heading, body) VALUES ('src-pl-bizlic-2025', 's2', 1, 'Renewals', 'Licenses must be renewed before the expiration date printed on the license. The renewal form must be submitted with any updated ownership or location information.');
INSERT INTO source_sections (source_id, id, ordinal, heading, body) VALUES ('src-pl-bizlic-2025', 's3', 2, 'Changes', 'Licensees must notify the Revenue Office of changes in ownership or business location.');
INSERT INTO permit_types (id, name, jurisdiction_id, authority, description, source_ids, fictional) VALUES ('pt-food', 'Food Service Establishment Plan Review', 'j-harrow', 'Harrow County Environmental Health Division', 'Plan review for new or remodeled food service establishments.', ARRAY['src-hc-food-2025']::text[], true);
